import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"回合奖励","description":"","frontmatter":{},"headers":[],"relativePath":"guide/round-bonus.md","filePath":"guide/round-bonus.md","lastUpdated":1790873127000}'),r={name:"guide/round-bonus.md"};function n(s,t,c,l,i,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="回合奖励" tabindex="-1">回合奖励 <a class="header-anchor" href="#回合奖励" aria-label="Permalink to &quot;回合奖励&quot;">​</a></h1><p>游戏开始时生成回合奖励表，为指定回合里正在行动的角色提供额外技能奖励。</p><div class="tip custom-block"><p class="custom-block-title">示例</p><p>第 10 回合 → 暴击率 <strong>+50%</strong></p></div><p>回合奖励在该回合结束时立即失效。在此基础上，v3.0 扩展了两种绑定方式、吟唱顺延与奖励的查询/追加/夺取。</p><h2 id="绑定方式" tabindex="-1">绑定方式 <a class="header-anchor" href="#绑定方式" aria-label="Permalink to &quot;绑定方式&quot;">​</a></h2><p>回合奖励支持两种绑定方式（<code>RoundRewardBinding</code>）：</p><table tabindex="0"><thead><tr><th>绑定方式</th><th>键位</th><th>说明</th></tr></thead><tbody><tr><td><code>Round</code>（默认）</td><td>全局回合数</td><td>所有角色在该回合共享同一份奖励表</td></tr><tr><td><code>Character</code></td><td>该角色的第 X 个<strong>行动回合</strong></td><td>每个角色有独立的奖励表；默认不启用，需在初始化时开启</td></tr></tbody></table><p>两种表<strong>可以同时启用并叠加</strong>：回合开始发放奖励时，先查回合绑定表中当前全局回合的项，再查角色绑定表中该角色当前行动回合的项，两处命中即全部发放。</p><h2 id="生成规则" tabindex="-1">生成规则 <a class="header-anchor" href="#生成规则" aria-label="Permalink to &quot;生成规则&quot;">​</a></h2><ul><li>沿用稀疏步进生成：相邻两个奖励之间随机间隔 1~8 个回合（<code>Random.Next(1, 9)</code>），每个命中的键位固定生成 <strong>1 个</strong>奖励（不再需要 <code>maxRound</code> / <code>maxRewardsInRound</code> 参数）</li><li>奖励表按 <strong>1000 键窗口</strong>滚动惰性物化（<code>GamingQueue.RoundRewardWindowSize</code>）：查询或发放跨过已生成范围时，按同一随机源自动物化下一窗口，不浪费随机数</li><li>奖励技能从初始化传入的特效池中随机构造，名称带 <code>[R]</code> 前缀，<code>SkillSource</code> 标记为 <code>Reward</code></li></ul><h2 id="发放与结算" tabindex="-1">发放与结算 <a class="header-anchor" href="#发放与结算" aria-label="Permalink to &quot;发放与结算&quot;">​</a></h2><p>每个行动回合的奖励生命周期：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>回合开始（TurnStart 事件之前）→ 发放奖励</span></span>
<span class="line"><span>    ├── 主动奖励 → 立即对自身施放（获得即释放），随后照常回收</span></span>
<span class="line"><span>    └── 被动奖励 → 挂载到角色技能栏（特效进入状态栏）</span></span>
<span class="line"><span>回合结束 → 结算奖励</span></span></code></pre></div><table tabindex="0"><thead><tr><th>回合如何结束</th><th>结算结果</th></tr></thead><tbody><tr><td>正常结束（含事件接管整回合）</td><td>全部回收</td></tr><tr><td>以<strong>吟唱</strong>或<strong>预释放爆发技</strong>结束</td><td>主动奖励照常回收；<strong>被动奖励顺延</strong>到该吟唱的结算回合</td></tr><tr><td>顺延后的结算回合结束</td><td>顺延奖励一并清除（无论该回合如何结束）</td></tr><tr><td>吟唱被打断 / 施法者死亡</td><td>已顺延的被动奖励<strong>立即清除</strong></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">技能受限时的例外（v3.0+）</p><p>回合奖励技能被标记为 <code>SkillSource.Reward</code> 来源。角色处于<strong>技能受限</strong>状态时，其他技能不可用，但 <strong>Reward 来源的奖励技能仍可释放</strong>。</p></div><h2 id="角色绑定的扩展操作" tabindex="-1">角色绑定的扩展操作 <a class="header-anchor" href="#角色绑定的扩展操作" aria-label="Permalink to &quot;角色绑定的扩展操作&quot;">​</a></h2><p>启用角色绑定后，可以通过 <code>IGamingQueue</code> 对<strong>未来的</strong>回合奖励进行查询、追加、移除和夺取（全部带事件与特效钩子，并写入回合日志事件流）：</p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>QueryRoundRewards(character, offset)</code></td><td>查询角色未来第 <code>offset</code> 个行动回合的奖励</td></tr><tr><td><code>AddRoundReward(character, offset, skill)</code></td><td>追加一条未来行动回合的奖励</td></tr><tr><td><code>RemoveRoundReward(character, offset, skill, out removed)</code></td><td>移除未来某行动回合中的一条奖励</td></tr><tr><td><code>RemoveRoundRewards(character, offset, out removed)</code></td><td>一次性移除未来某行动回合的<strong>全部</strong>奖励</td></tr><tr><td><code>StealRoundReward(target, fromOffset, thief, toOffset, out stolen)</code></td><td>夺取目标某行动回合的全部奖励，并入夺取者的指定行动回合</td></tr></tbody></table><p>统一约定：</p><ul><li><strong>offset 语义</strong>：相对各自当前行动回合的偏移，最小为 1（1 = 下一个行动回合）</li><li><strong>召唤物折算</strong>：召唤物（<code>Master</code> 非空）不单独享受角色绑定奖励，查询/追加/夺取统一折算到其 <code>Master</code> 名下；但对召唤物的移除不会误伤 <code>Master</code></li><li>夺取语义为<strong>引用转移</strong>：目标键位的全部奖励一次性转移并与夺取者目标键位的奖励合并，来源登记同步改到夺取者侧</li><li>这些操作仅在启用角色绑定时可用（未启用时返回 <code>false</code> / 空列表）</li></ul><h2 id="事件与钩子" tabindex="-1">事件与钩子 <a class="header-anchor" href="#事件与钩子" aria-label="Permalink to &quot;事件与钩子&quot;">​</a></h2><p>奖励管线的每个节点（发放 / 移除 / 夺取）都会构造一份 <code>RoundRewardContext</code>，同一实例依次流经 <strong>队列事件 → 特效钩子</strong>，并写入回合日志的奖励事件流（见 <a href="/api/RoundRewardRecord.html">RoundRewardRecord</a>）：</p><table tabindex="0"><thead><tr><th>节点</th><th>队列事件（Before / After）</th><th>特效钩子</th></tr></thead><tbody><tr><td>获得奖励</td><td><code>GamingRoundRewardGainedBefore/After</code></td><td><code>OnRoundRewardGained</code></td></tr><tr><td>失去奖励</td><td><code>GamingRoundRewardLostBefore/After</code></td><td><code>OnRoundRewardLost</code></td></tr><tr><td>奖励被夺取</td><td><code>GamingRoundRewardStolenBefore/After</code></td><td><code>OnRoundRewardStolen</code>（原持有者与夺取者的特效都会触发）</td></tr></tbody></table><p>特效内部也可用 <code>QueryRoundReward</code> / <code>AddRoundReward</code> / <code>RemoveRoundReward(s)</code> / <code>StealRoundReward</code> 等保护方法操作奖励，见 <a href="/api/Effect.html#特效内部可用方法">Effect</a>。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>API → <a href="/api/GamingQueue.html#回合奖励">GamingQueue</a> / <a href="/api/RoundRewardRecord.html">RoundRewardRecord</a> / <a href="/api/HookContext.html">RoundRewardContext</a></li><li>奖励事件 → <a href="/dev/events-overview.html#七、回合奖励事件-6-个-—-通知型">GamingQueue 事件模式</a></li></ul>`,26)])])}const R=e(r,[["render",n]]);export{p as __pageData,R as default};
